`timescale 1ns/1ps
// P36 instance-wide fence successor around the unchanged P35 production hierarchy.
module a0_production_atomic_fenced_subsystem #(
    parameter integer FENCE_SOURCE_W=4,
    parameter integer FENCE_CONTEXT_W=4,
    parameter integer FENCE_REQUEST_ID_W=8,
    parameter integer FENCE_GENERATION_W=2,
    parameter integer ATOMIC_SOURCE_W=4,
    parameter integer ATOMIC_CONTEXT_W=4,
    parameter integer ATOMIC_REQUEST_ID_W=8,
    parameter integer ATOMIC_GENERATION_W=2,
    parameter integer ATOMIC_ENTRY_COUNT=4,
    parameter integer COHERENCE_NODE_W = 4,
    parameter integer COHERENCE_TXN_W = 4,
    parameter integer COHERENCE_GEN_W = 2,
    parameter logic [COHERENCE_NODE_W-1:0] LOCAL_NODE_ID = '0,
    parameter integer CLIENT_COUNT = 4,
    parameter integer LOCAL_TAG_W = 2,
    parameter integer CLIENT_MAX_OUTSTANDING = 4,
    parameter integer COMMIT_PORT_COUNT = 4,
    parameter integer STORE_LANES = 32,
    parameter integer SLICE_COUNT = 4,
    parameter integer LINE_WORDS = 8,
    parameter integer SET_COUNT_PER_SLICE = 64,
    parameter integer WRITE_ID_W = 8,
    parameter integer MAX_WB_RETRIES = 2,
    parameter integer STORE_WRITE_ID_W = 8,
    parameter integer MAX_STORE_RETRIES = 2,
    parameter integer WORD_SELECT_W = (LINE_WORDS <= 1) ? 0 : $clog2(LINE_WORDS),
    parameter integer LINE_ADDR_W = 32 - WORD_SELECT_W,
    parameter integer CLIENT_ID_W = $clog2(CLIENT_COUNT+1),
    parameter integer GLOBAL_TAG_W = CLIENT_ID_W + LOCAL_TAG_W,
    parameter integer SLICE_ID_W = (SLICE_COUNT <= 1) ? 1 : $clog2(SLICE_COUNT),
    parameter integer SLICE_HASH_SHIFT = (SET_COUNT_PER_SLICE <= 1) ? 0 : $clog2(SET_COUNT_PER_SLICE),
    parameter integer RETRY_W = (MAX_WB_RETRIES < 1) ? 1 : $clog2(MAX_WB_RETRIES + 1),
    parameter integer LOCAL_ATTEMPT_ID_W = WRITE_ID_W + RETRY_W,
    parameter integer BACKEND_ATTEMPT_ID_W = SLICE_ID_W + LOCAL_ATTEMPT_ID_W,
    parameter integer BACKEND_READ_TAG_W = SLICE_ID_W + GLOBAL_TAG_W,
    parameter integer COUNT_W = (SLICE_COUNT <= 1) ? 1 : $clog2(SLICE_COUNT + 1),
    parameter integer STORE_RETRY_W = (MAX_STORE_RETRIES < 1) ? 1 : $clog2(MAX_STORE_RETRIES + 1),
    parameter integer STORE_GENERATION_W = 8,
    parameter integer P29_STORE_ATTEMPT_ID_W = STORE_WRITE_ID_W + STORE_RETRY_W,
    parameter integer STORE_ATTEMPT_ID_W = STORE_GENERATION_W + P29_STORE_ATTEMPT_ID_W,
    parameter integer STORE_STATUS_TIMEOUT_CYCLES = 16,
    parameter integer STORE_STATUS_TIMER_W = (STORE_STATUS_TIMEOUT_CYCLES <= 1) ? 1 : $clog2(STORE_STATUS_TIMEOUT_CYCLES),
    parameter integer COMMIT_PORT_ID_W = (COMMIT_PORT_COUNT <= 1) ? 1 : $clog2(COMMIT_PORT_COUNT),
    parameter integer CLIENT_READ_COUNT_W = (((CLIENT_COUNT+1) * CLIENT_MAX_OUTSTANDING) < 1)
        ? 1 : $clog2((CLIENT_COUNT+1) * CLIENT_MAX_OUTSTANDING + 1)
) (
    input logic fence_req_valid_i,
    output logic fence_req_ready_o,
    input logic [FENCE_SOURCE_W-1:0] fence_req_source_i,
    input logic [FENCE_CONTEXT_W-1:0] fence_req_context_i,
    input logic [FENCE_REQUEST_ID_W-1:0] fence_req_request_id_i,
    input logic [FENCE_GENERATION_W-1:0] fence_req_generation_i,
    input logic fence_req_acquire_i,fence_req_release_i,
    output logic fence_resp_valid_o,
    input logic fence_resp_ready_i,
    output logic [FENCE_SOURCE_W-1:0] fence_resp_source_o,
    output logic [FENCE_CONTEXT_W-1:0] fence_resp_context_o,
    output logic [FENCE_REQUEST_ID_W-1:0] fence_resp_request_id_o,
    output logic [FENCE_GENERATION_W-1:0] fence_resp_generation_o,
    output logic fence_resp_acquire_o,fence_resp_release_o,
    output logic [4:0] fence_resp_fault_bits_o,
    output logic fence_busy_o,fence_protocol_error_o,
    output logic [COMMIT_PORT_COUNT-1:0] fence_pending_store_o,
    output logic atomic_new_issue_o,atomic_issue_rejected_o,
    output logic atomic_transport_duplicate_o,atomic_response_rejected_o,atomic_transport_replay_o,
    output logic [$clog2(ATOMIC_ENTRY_COUNT+1)-1:0] atomic_requester_outstanding_o,
    input logic atomic_req_valid_i,
    output logic atomic_req_ready_o,
    input logic [ATOMIC_SOURCE_W-1:0] atomic_req_source_i,
    input logic [ATOMIC_CONTEXT_W-1:0] atomic_req_context_i,
    input logic [ATOMIC_REQUEST_ID_W-1:0] atomic_req_request_id_i,
    input logic [ATOMIC_GENERATION_W-1:0] atomic_req_generation_i,
    input logic [31:0] atomic_req_word_addr_i,
    input logic atomic_req_is64_i,
    input logic [3:0] atomic_req_op_i,
    input logic [63:0] atomic_req_operand_i,atomic_req_compare_i,
    output logic atomic_retire_valid_o,
    input logic atomic_retire_ready_i,
    output logic [ATOMIC_SOURCE_W-1:0] atomic_retire_source_o,
    output logic [ATOMIC_CONTEXT_W-1:0] atomic_retire_context_o,
    output logic [ATOMIC_REQUEST_ID_W-1:0] atomic_retire_request_id_o,
    output logic [ATOMIC_GENERATION_W-1:0] atomic_retire_generation_o,
    output logic [31:0] atomic_retire_word_addr_o,
    output logic atomic_retire_is64_o,
    output logic [3:0] atomic_retire_op_o,
    output logic [63:0] atomic_retire_operand_o,atomic_retire_compare_o,atomic_retire_old_o,
    output logic atomic_retire_cas_success_o,
    output logic [3:0] atomic_retire_fault_o,
    input logic atomic_epoch_advance_valid_i,
    output logic atomic_epoch_advance_ready_o,
    input logic atomic_epoch_quiescent_i,atomic_all_generations_quiescent_i,
    output logic [ATOMIC_GENERATION_W-1:0] atomic_current_generation_o,
    output logic atomic_epoch_advance_pulse_o,atomic_table_full_o,atomic_busy_o,atomic_protocol_error_o,
    input logic clk,
    input logic rst_n,

    input logic [CLIENT_COUNT-1:0] client_req_valid_i,
    output logic [CLIENT_COUNT-1:0] client_req_ready_o,
    input logic [LOCAL_TAG_W-1:0] client_req_local_tag_i [0:CLIENT_COUNT-1],
    input logic [LINE_ADDR_W-1:0] client_req_line_addr_i [0:CLIENT_COUNT-1],
    output logic [CLIENT_COUNT-1:0] client_resp_valid_o,
    output logic [LOCAL_TAG_W-1:0] client_resp_local_tag_o [0:CLIENT_COUNT-1],
    output logic [LINE_ADDR_W-1:0] client_resp_line_addr_o [0:CLIENT_COUNT-1],
    output logic client_resp_fault_o [0:CLIENT_COUNT-1],
    output logic [31:0] client_resp_data_o [0:CLIENT_COUNT-1][0:LINE_WORDS-1],

    input logic [COMMIT_PORT_COUNT-1:0] commit_valid_i,
    output logic [COMMIT_PORT_COUNT-1:0] commit_ready_o,
    input logic [STORE_LANES-1:0] commit_lane_mask_i [0:COMMIT_PORT_COUNT-1],
    input logic [31:0] commit_word_addr_i [0:COMMIT_PORT_COUNT-1][0:STORE_LANES-1],
    input logic [31:0] commit_wdata_i [0:COMMIT_PORT_COUNT-1][0:STORE_LANES-1],

    output logic backend_cmd_valid_o,
    input logic backend_cmd_ready_i,
    output logic [1:0] backend_cmd_kind_o,
    output logic [BACKEND_READ_TAG_W-1:0] backend_cmd_read_tag_o,
    output logic [BACKEND_ATTEMPT_ID_W-1:0] backend_cmd_wb_attempt_id_o,
    output logic [STORE_ATTEMPT_ID_W-1:0] backend_cmd_store_attempt_id_o,
    output logic [LINE_ADDR_W-1:0] backend_cmd_line_addr_o,
    output logic [31:0] backend_cmd_data_o [0:LINE_WORDS-1],
    output logic [31:0] backend_cmd_store_word_addr_o,
    output logic [31:0] backend_cmd_store_wdata_o,

    input logic backend_read_resp_valid_i,
    input logic [BACKEND_READ_TAG_W-1:0] backend_read_resp_tag_i,
    input logic [LINE_ADDR_W-1:0] backend_read_resp_line_addr_i,
    input logic backend_read_resp_fault_i,
    input logic [31:0] backend_read_resp_data_i [0:LINE_WORDS-1],
    input logic backend_wb_status_valid_i,
    input logic [BACKEND_ATTEMPT_ID_W-1:0] backend_wb_status_attempt_id_i,
    input logic backend_wb_status_success_i,
    input logic backend_wb_status_retryable_i,
    input logic backend_store_status_valid_i,
    input logic [STORE_ATTEMPT_ID_W-1:0] backend_store_status_attempt_id_i,
    input logic backend_store_status_success_i,
    input logic backend_store_status_retryable_i,
    input logic backend_store_status_reuse_safe_i,
    input logic backend_store_all_generations_quiescent_i,
    input logic [SLICE_COUNT-1:0] backend_wb_recovery_safe_valid_i,
    output logic [SLICE_COUNT-1:0] backend_wb_recovery_safe_ready_o,

    output logic [SLICE_COUNT-1:0] dirty_present_o,
    output logic [SLICE_COUNT-1:0] wb_busy_o,
    output logic [RETRY_W-1:0] wb_retry_count_o [0:SLICE_COUNT-1],
    output logic [SLICE_COUNT-1:0] wb_terminal_failure_o,
    output logic [SLICE_COUNT-1:0] recovery_active_o,
    output logic [SLICE_COUNT-1:0] recovery_complete_pulse_o,
    output logic [COUNT_W-1:0] wb_pending_count_o,
    output logic [COUNT_W-1:0] wb_active_count_o,
    output logic commit_visibility_busy_o,
    output logic store_completion_busy_o,
    output logic [STORE_RETRY_W-1:0] store_retry_count_o,
    output logic store_terminal_failure_o,
    output logic line_resp_tag_error_o,
    output logic line_resp_overflow_o,
    output logic store_status_timeout_live_o,
    output logic [STORE_STATUS_TIMER_W-1:0] store_status_timeout_age_o,
    output logic store_status_timeout_pulse_o,
    output logic store_status_timeout_seen_o,
    output logic [COMMIT_PORT_COUNT-1:0] commit_abort_o,
    output logic commit_fault_valid_o,
    input logic commit_fault_ready_i,
    output logic [COMMIT_PORT_ID_W-1:0] commit_fault_port_id_o,
    output logic [STORE_LANES-1:0] commit_fault_lane_mask_o,
    output logic [31:0] commit_fault_word_addr_o [0:STORE_LANES-1],
    output logic [31:0] commit_fault_wdata_o [0:STORE_LANES-1],
    output logic commit_fault_store_timeout_o,
    output logic [STORE_RETRY_W-1:0] commit_fault_store_retry_count_o,
    output logic recovery_required_o,
    output logic recovery_rearm_pulse_o,
    output logic recovery_drain_active_o,
    output logic [STORE_GENERATION_W-1:0] store_generation_next_o,
    output logic store_generation_wrap_pending_o,
    output logic store_status_rejected_o,
    output logic recovery_reset_blocked_o,
    output logic [CLIENT_READ_COUNT_W-1:0] client_read_outstanding_o,
    output logic [CLIENT_COUNT-1:0] client_store_conflict_o,
    output logic [COMMIT_PORT_COUNT-1:0] commit_read_wait_o,
    input logic [SLICE_COUNT-1:0] probe_reuse_safe_i,
    output logic [SET_COUNT_PER_SLICE-1:0] coherence_block_set_o [0:SLICE_COUNT-1],
    output logic [SLICE_COUNT-1:0] remote_owned_present_o,
    output logic [SLICE_COUNT-1:0] probe_generation_exhausted_o,
    output logic coherence_protocol_error_o,
    output logic protocol_error_o
);

    logic allow_new,drain_quiet,any_client_fault;
    logic [COMMIT_PORT_COUNT-1:0] store_allow,child_commit_ready,child_commit_abort;
    logic [CLIENT_COUNT-1:0] child_client_req_ready;
    logic child_atomic_req_ready,child_atomic_epoch_ready;

    assign client_req_ready_o=child_client_req_ready & {CLIENT_COUNT{allow_new}};
    assign atomic_req_ready_o=child_atomic_req_ready && allow_new;
    assign atomic_epoch_advance_ready_o=child_atomic_epoch_ready && allow_new;
    // Success-ready and abort remain separate real terminal events.
    assign commit_ready_o=child_commit_ready & store_allow;
    assign commit_abort_o=child_commit_abort & store_allow;

    // Resident dirty data and retired atomic tombstones do not imply live work.
    // Current response/status pulses impose one quiet edge after delivery.
    assign drain_quiet=(client_read_outstanding_o=='0)
        // NEGATIVE FIXTURE ONLY: omit all three architectural atomic-drain guards.
        && !atomic_epoch_advance_pulse_o && !(|client_resp_valid_o)
        && !commit_visibility_busy_o && !store_completion_busy_o
        && !store_terminal_failure_o && !commit_fault_valid_o
        && !recovery_required_o && !recovery_drain_active_o
        && !(|wb_busy_o) && (wb_pending_count_o=='0) && (wb_active_count_o=='0)
        && !(|wb_terminal_failure_o) && !(|recovery_active_o)
        && !(|recovery_complete_pulse_o) && !recovery_rearm_pulse_o
        && !backend_cmd_valid_o && !backend_read_resp_valid_i
        && !backend_wb_status_valid_i && !backend_store_status_valid_i
        && !protocol_error_o && !coherence_protocol_error_o;

    always_comb begin
        any_client_fault=1'b0;
        for(integer client=0;client<CLIENT_COUNT;client=client+1)
            any_client_fault=any_client_fault || (client_resp_valid_o[client] && client_resp_fault_o[client]);
    end

    a0_memory_drain_fence_controller #(
        .SOURCE_W(FENCE_SOURCE_W),.CONTEXT_W(FENCE_CONTEXT_W),
        .REQUEST_ID_W(FENCE_REQUEST_ID_W),.GENERATION_W(FENCE_GENERATION_W),
        .COMMIT_PORT_COUNT(COMMIT_PORT_COUNT),.STORE_LANES(STORE_LANES)
    ) u_fence (
        .clk(clk),.rst_n(rst_n),
        .fence_req_valid_i(fence_req_valid_i),.fence_req_ready_o(fence_req_ready_o),
        .fence_req_source_i(fence_req_source_i),.fence_req_context_i(fence_req_context_i),
        .fence_req_request_id_i(fence_req_request_id_i),.fence_req_generation_i(fence_req_generation_i),
        .fence_req_acquire_i(fence_req_acquire_i),.fence_req_release_i(fence_req_release_i),
        .fence_resp_valid_o(fence_resp_valid_o),.fence_resp_ready_i(fence_resp_ready_i),
        .fence_resp_source_o(fence_resp_source_o),.fence_resp_context_o(fence_resp_context_o),
        .fence_resp_request_id_o(fence_resp_request_id_o),.fence_resp_generation_o(fence_resp_generation_o),
        .fence_resp_acquire_o(fence_resp_acquire_o),.fence_resp_release_o(fence_resp_release_o),
        .fence_resp_fault_bits_o(fence_resp_fault_bits_o),
        .commit_valid_i(commit_valid_i),.commit_lane_mask_i(commit_lane_mask_i),
        .commit_word_addr_i(commit_word_addr_i),.commit_wdata_i(commit_wdata_i),
        .store_complete_i(child_commit_ready),.store_abort_i(child_commit_abort),
        .drain_quiet_i(drain_quiet),.inherited_protocol_error_i(protocol_error_o),
        .read_fault_event_i(any_client_fault),
        .atomic_fault_event_i(atomic_retire_valid_o && atomic_retire_ready_i && (atomic_retire_fault_o!='0)),
        .store_fault_event_i(commit_fault_valid_o),
        .wb_terminal_failure_event_i(|wb_terminal_failure_o),
        .allow_new_o(allow_new),.store_allow_o(store_allow),
        .fence_busy_o(fence_busy_o),.fence_protocol_error_o(fence_protocol_error_o),
        .fence_pending_store_o(fence_pending_store_o)
    );

    a0_production_atomic_retiring_subsystem #(
        .ATOMIC_SOURCE_W(ATOMIC_SOURCE_W),
        .ATOMIC_CONTEXT_W(ATOMIC_CONTEXT_W),
        .ATOMIC_REQUEST_ID_W(ATOMIC_REQUEST_ID_W),
        .ATOMIC_GENERATION_W(ATOMIC_GENERATION_W),
        .ATOMIC_ENTRY_COUNT(ATOMIC_ENTRY_COUNT),
        .COHERENCE_NODE_W(COHERENCE_NODE_W),
        .COHERENCE_TXN_W(COHERENCE_TXN_W),
        .COHERENCE_GEN_W(COHERENCE_GEN_W),
        .LOCAL_NODE_ID(LOCAL_NODE_ID),
        .CLIENT_COUNT(CLIENT_COUNT),
        .LOCAL_TAG_W(LOCAL_TAG_W),
        .CLIENT_MAX_OUTSTANDING(CLIENT_MAX_OUTSTANDING),
        .COMMIT_PORT_COUNT(COMMIT_PORT_COUNT),
        .STORE_LANES(STORE_LANES),
        .SLICE_COUNT(SLICE_COUNT),
        .LINE_WORDS(LINE_WORDS),
        .SET_COUNT_PER_SLICE(SET_COUNT_PER_SLICE),
        .WRITE_ID_W(WRITE_ID_W),
        .MAX_WB_RETRIES(MAX_WB_RETRIES),
        .STORE_WRITE_ID_W(STORE_WRITE_ID_W),
        .MAX_STORE_RETRIES(MAX_STORE_RETRIES),
        .WORD_SELECT_W(WORD_SELECT_W),
        .LINE_ADDR_W(LINE_ADDR_W),
        .CLIENT_ID_W(CLIENT_ID_W),
        .GLOBAL_TAG_W(GLOBAL_TAG_W),
        .SLICE_ID_W(SLICE_ID_W),
        .SLICE_HASH_SHIFT(SLICE_HASH_SHIFT),
        .RETRY_W(RETRY_W),
        .LOCAL_ATTEMPT_ID_W(LOCAL_ATTEMPT_ID_W),
        .BACKEND_ATTEMPT_ID_W(BACKEND_ATTEMPT_ID_W),
        .BACKEND_READ_TAG_W(BACKEND_READ_TAG_W),
        .COUNT_W(COUNT_W),
        .STORE_RETRY_W(STORE_RETRY_W),
        .STORE_GENERATION_W(STORE_GENERATION_W),
        .P29_STORE_ATTEMPT_ID_W(P29_STORE_ATTEMPT_ID_W),
        .STORE_ATTEMPT_ID_W(STORE_ATTEMPT_ID_W),
        .STORE_STATUS_TIMEOUT_CYCLES(STORE_STATUS_TIMEOUT_CYCLES),
        .STORE_STATUS_TIMER_W(STORE_STATUS_TIMER_W),
        .COMMIT_PORT_ID_W(COMMIT_PORT_ID_W),
        .CLIENT_READ_COUNT_W(CLIENT_READ_COUNT_W)
    ) u_memory (
        .atomic_new_issue_o(atomic_new_issue_o),
        .atomic_issue_rejected_o(atomic_issue_rejected_o),
        .atomic_transport_duplicate_o(atomic_transport_duplicate_o),
        .atomic_response_rejected_o(atomic_response_rejected_o),
        .atomic_transport_replay_o(atomic_transport_replay_o),
        .atomic_requester_outstanding_o(atomic_requester_outstanding_o),
        .atomic_req_valid_i(atomic_req_valid_i && allow_new),
        .atomic_req_ready_o(child_atomic_req_ready),
        .atomic_req_source_i(atomic_req_source_i),
        .atomic_req_context_i(atomic_req_context_i),
        .atomic_req_request_id_i(atomic_req_request_id_i),
        .atomic_req_generation_i(atomic_req_generation_i),
        .atomic_req_word_addr_i(atomic_req_word_addr_i),
        .atomic_req_is64_i(atomic_req_is64_i),
        .atomic_req_op_i(atomic_req_op_i),
        .atomic_req_operand_i(atomic_req_operand_i),
        .atomic_req_compare_i(atomic_req_compare_i),
        .atomic_retire_valid_o(atomic_retire_valid_o),
        .atomic_retire_ready_i(atomic_retire_ready_i),
        .atomic_retire_source_o(atomic_retire_source_o),
        .atomic_retire_context_o(atomic_retire_context_o),
        .atomic_retire_request_id_o(atomic_retire_request_id_o),
        .atomic_retire_generation_o(atomic_retire_generation_o),
        .atomic_retire_word_addr_o(atomic_retire_word_addr_o),
        .atomic_retire_is64_o(atomic_retire_is64_o),
        .atomic_retire_op_o(atomic_retire_op_o),
        .atomic_retire_operand_o(atomic_retire_operand_o),
        .atomic_retire_compare_o(atomic_retire_compare_o),
        .atomic_retire_old_o(atomic_retire_old_o),
        .atomic_retire_cas_success_o(atomic_retire_cas_success_o),
        .atomic_retire_fault_o(atomic_retire_fault_o),
        .atomic_epoch_advance_valid_i(atomic_epoch_advance_valid_i && allow_new),
        .atomic_epoch_advance_ready_o(child_atomic_epoch_ready),
        .atomic_epoch_quiescent_i(atomic_epoch_quiescent_i),
        .atomic_all_generations_quiescent_i(atomic_all_generations_quiescent_i),
        .atomic_current_generation_o(atomic_current_generation_o),
        .atomic_epoch_advance_pulse_o(atomic_epoch_advance_pulse_o),
        .atomic_table_full_o(atomic_table_full_o),
        .atomic_busy_o(atomic_busy_o),
        .atomic_protocol_error_o(atomic_protocol_error_o),
        .clk(clk),
        .rst_n(rst_n),
        .client_req_valid_i(client_req_valid_i & {CLIENT_COUNT{allow_new}}),
        .client_req_ready_o(child_client_req_ready),
        .client_req_local_tag_i(client_req_local_tag_i),
        .client_req_line_addr_i(client_req_line_addr_i),
        .client_resp_valid_o(client_resp_valid_o),
        .client_resp_local_tag_o(client_resp_local_tag_o),
        .client_resp_line_addr_o(client_resp_line_addr_o),
        .client_resp_fault_o(client_resp_fault_o),
        .client_resp_data_o(client_resp_data_o),
        .commit_valid_i(commit_valid_i & store_allow),
        .commit_ready_o(child_commit_ready),
        .commit_lane_mask_i(commit_lane_mask_i),
        .commit_word_addr_i(commit_word_addr_i),
        .commit_wdata_i(commit_wdata_i),
        .backend_cmd_valid_o(backend_cmd_valid_o),
        .backend_cmd_ready_i(backend_cmd_ready_i),
        .backend_cmd_kind_o(backend_cmd_kind_o),
        .backend_cmd_read_tag_o(backend_cmd_read_tag_o),
        .backend_cmd_wb_attempt_id_o(backend_cmd_wb_attempt_id_o),
        .backend_cmd_store_attempt_id_o(backend_cmd_store_attempt_id_o),
        .backend_cmd_line_addr_o(backend_cmd_line_addr_o),
        .backend_cmd_data_o(backend_cmd_data_o),
        .backend_cmd_store_word_addr_o(backend_cmd_store_word_addr_o),
        .backend_cmd_store_wdata_o(backend_cmd_store_wdata_o),
        .backend_read_resp_valid_i(backend_read_resp_valid_i),
        .backend_read_resp_tag_i(backend_read_resp_tag_i),
        .backend_read_resp_line_addr_i(backend_read_resp_line_addr_i),
        .backend_read_resp_fault_i(backend_read_resp_fault_i),
        .backend_read_resp_data_i(backend_read_resp_data_i),
        .backend_wb_status_valid_i(backend_wb_status_valid_i),
        .backend_wb_status_attempt_id_i(backend_wb_status_attempt_id_i),
        .backend_wb_status_success_i(backend_wb_status_success_i),
        .backend_wb_status_retryable_i(backend_wb_status_retryable_i),
        .backend_store_status_valid_i(backend_store_status_valid_i),
        .backend_store_status_attempt_id_i(backend_store_status_attempt_id_i),
